<template><section class="space-y-6"><div class="rounded-2xl border border-amber-500/20 bg-gradient-to-r from-amber-500/10 to-transparent p-6"><p class="text-xs font-semibold tracking-[0.18em] text-amber-700 dark:text-amber-300">ATELIÊ</p><h1 class="mt-1 text-3xl font-bold">Comissões</h1><p class="mt-1 text-sm text-muted-foreground">Splits consolidados na revisão e quitação pelo financeiro.</p></div><Card><CardContent class="p-0"><div v-for="commission in commissions" :key="commission.id" class="flex flex-col justify-between gap-3 border-b p-5 sm:flex-row sm:items-center"><div><p class="font-semibold">{{ commission.usuario?.nome || 'Ourive' }}</p><p class="text-sm text-muted-foreground">Etapa #{{ commission.etapaId }} · {{ commission.tipo === 'PERCENTUAL' ? `${commission.referencia}%` : money(commission.referencia) }}</p></div><div class="flex items-center gap-3"><Badge :variant="commission.quitadaEm ? 'default' : commission.valorConsolidado ? 'secondary' : 'outline'">{{ commission.quitadaEm ? 'Quitada' : commission.valorConsolidado ? money(commission.valorConsolidado) : 'Aguardando revisão' }}</Badge><Button v-if="canFinance && commission.lancamentoFinanceiroId && !commission.quitadaEm" size="sm" @click="settle(commission)">Quitar</Button></div></div><div v-if="!commissions.length" class="p-10 text-center text-sm text-muted-foreground">Nenhuma comissão disponível.</div></CardContent></Card></section></template>
<script setup lang="ts">import { onMounted, ref } from 'vue'; import { useToast } from 'vue-toastification'; import { Button } from '@/components/ui/button'; import { Badge } from '@/components/ui/badge'; import { Card, CardContent } from '@/components/ui/card'; import { OuriveRepository } from '@/repositories/ourive-repository'; import { useUiStore } from '@/stores/ui/uiStore'; const toast = useToast(); const ui = useUiStore(); const commissions = ref<any[]>([]); const canFinance = ui.hasOuriveCapability('FINANCEIRO'); const money = (value: unknown) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(Number(value || 0)); async function load() { try { commissions.value = await OuriveRepository.comissoes() } catch { toast.error('Não foi possível carregar as comissões.') } } async function settle(commission: any) { try { await OuriveRepository.quitarComissao(commission.id); await load(); toast.success('Comissão quitada e lançamento financeiro efetivado.') } catch (error: any) { toast.error(error?.response?.data?.error?.message || 'Não foi possível quitar a comissão.') } } onMounted(load)</script>
